ADukeSquad::ADukeSquad() { PrimaryActorTick.bCanEverTick = true; }
float ADukeSquad::Now() const { return GetWorld()->GetTimeSeconds(); }

TArray<ADukeTrooper*> ADukeSquad::Alive() const
{
	TArray<ADukeTrooper*> Out;
	for (const TObjectPtr<ADukeTrooper>& M : Members) if (M && !M->IsDead()) Out.Add(M.Get());
	return Out;
}

ADukeTrooper* ADukeSquad::Leader() const
{
	ADukeTrooper* Best = nullptr;
	for (ADukeTrooper* M : Alive()) if (!M->IsWounded() && (!Best || M->Rank > Best->Rank)) Best = M;   // chain of command
	return Best;
}

void ADukeSquad::BeginPlay()
{
	Super::BeginPlay();
	for (const TObjectPtr<ADukeTrooper>& M : Members) if (M) M->Squad = this;
	if (Checkpoint) Checkpoint->Squad = this;
	AssignDuties();
	ModeSince = Now();
}

// Default table of organisation if the level designer left everyone as Rifleman.
void ADukeSquad::AssignDuties()
{
	bool bAllDefault = true;
	for (const TObjectPtr<ADukeTrooper>& M : Members) if (M && (M->Duty != EDukeDuty::Rifleman || M->Rank != EDukeRank::Trooper)) bAllDefault = false;
	if (!bAllDefault) return;
	static const EDukeRank Ranks[] = { EDukeRank::Officer, EDukeRank::Sergeant, EDukeRank::Corporal };
	static const EDukeDuty Duties[] = { EDukeDuty::Rifleman, EDukeDuty::Rifleman, EDukeDuty::Radio, EDukeDuty::Medic, EDukeDuty::Heavy,
		EDukeDuty::Logistics, EDukeDuty::Artillery, EDukeDuty::Checkpoint, EDukeDuty::Checkpoint, EDukeDuty::Logistics, EDukeDuty::Rifleman };
	for (int32 i = 0; i < Members.Num(); ++i)
	{
		if (!Members[i]) continue;
		if (i < 3) Members[i]->Rank = Ranks[i];
		Members[i]->Duty = Duties[FMath::Min(i, (int32)UE_ARRAY_COUNT(Duties) - 1)];
		if (Members[i]->Duty == EDukeDuty::Checkpoint && !Checkpoint) Members[i]->Duty = EDukeDuty::Rifleman;
	}
}

void ADukeSquad::ReportThreat(ADukeTrooper* Reporter, AActor* InThreat)
{
	if (!InThreat) return;
	const bool bNew = !Threat.IsValid();
	Threat = InThreat; ThreatLastSeen = InThreat->GetActorLocation(); ThreatTime = Now();
	if (bNew)
	{
		NextBound = Now() + 1.f;
		// the radio operator calls it in, the leader gives the order
		for (ADukeTrooper* M : Alive())
		{
			if (M->Duty == EDukeDuty::Radio) M->PlayGesture(TEXT("radio_call"));
			if (M == Leader()) M->PlayGesture(TEXT("command_point"));
		}
	}
}

void ADukeSquad::ReportWounded(ADukeTrooper* W) { if (W && !Rescues.Contains(W)) Rescues.Add(W, nullptr); }
void ADukeSquad::ReportDown(ADukeTrooper* D) { Rescues.Remove(D); }

bool ADukeSquad::HasLineOfSight(const FVector& A, const FVector& B) const
{
	FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeSquadLOS), false);
	for (const TObjectPtr<ADukeTrooper>& M : Members) if (M) Q.AddIgnoredActor(M.Get());
	if (Threat.IsValid()) Q.AddIgnoredActor(Threat.Get());
	FHitResult H;
	return !GetWorld()->LineTraceSingleByChannel(H, A, B, ECC_Visibility, Q);
}

// Cover = a spot on the ground where the threat cannot see a crouching trooper (60 cm), nearest to Near.
bool ADukeSquad::FindCover(const FVector& Near, const FVector& From, FVector& Out) const
{
	float Best = 1e9f; bool bFound = false;
	const FVector Eye = From + FVector(0, 0, 80.f);
	for (float R = 250.f; R <= CoverSearchRadius; R += 160.f)
		for (int32 k = 0; k < 16; ++k)
		{
			const float A = k * PI / 8.f;
			FVector P = Near + FVector(FMath::Cos(A) * R, FMath::Sin(A) * R, 0.f);
			FHitResult G; FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeCoverGround), false);
			if (!GetWorld()->LineTraceSingleByChannel(G, P + FVector(0, 0, 300), P - FVector(0, 0, 600), ECC_Visibility, Q)) continue;
			P = G.ImpactPoint;
			if (HasLineOfSight(Eye, P + FVector(0, 0, 60.f))) continue;          // exposed
			if (!HasLineOfSight(P + FVector(0, 0, 150.f), Eye)) continue;         // must still be able to pop up and shoot
			const float D = FVector::Dist(P, Near);
			if (D < Best) { Best = D; Out = P; bFound = true; }
		}
	return bFound;
}

void ADukeSquad::Tick(float Dt)
{
	Super::Tick(Dt);
	const float T = Now();
	// artillery shells land 3 s after the mortar crew drops them
	for (int32 i = GStrikes.Num() - 1; i >= 0; --i)
		if (T >= GStrikes[i].When)
		{
			UGameplayStatics::ApplyRadialDamage(this, 120.f, GStrikes[i].At, 450.f, UDukeExplosionDamageType::StaticClass(), TArray<AActor*>(), this, nullptr, false);
			GStrikes.RemoveAt(i);
		}
	if (Threat.IsValid() && T - ThreatTime < 20.f) TickCombat(Dt);
	else { Threat = nullptr; if (Mode == EDukeSquadMode::ClearBuilding) TickClearBuilding(); else TickPeace(Dt); }
	TickRescues();
}

void ADukeSquad::TickPeace(float Dt)
{
	const float T = Now();
	ADukeTrooper* L = Leader();
	if (!L) return;
	TArray<ADukeTrooper*> A = Alive();
	const FVector Base = GetActorLocation();
	auto Give = [&](ADukeTrooper* M, EDukeOrder Ty, const FVector& Loc, FName Clip = NAME_None, AActor* Face = nullptr)
	{
		if (M->IsWounded() || M->IsBusyRescuing()) return;
		FDukeOrderData O; O.Type = Ty; O.Location = Loc; O.Clip = Clip; O.Target = Face; M->GiveOrder(O);
	};
	if (Mode == EDukeSquadMode::Patrol)
	{
		// the leader walks the route; the squad follows in a staggered file
		const FVector Goal = PatrolRoute.Num() ? GetActorTransform().TransformPosition(PatrolRoute[PatrolIndex % PatrolRoute.Num()]) : Base;
		if (FVector::Dist2D(L->GetActorLocation(), Goal) < 120.f && PatrolRoute.Num()) PatrolIndex = (PatrolIndex + 1) % PatrolRoute.Num();
		Give(L, EDukeOrder::Move, Goal);
		int32 i = 0;
		for (ADukeTrooper* M : A)
		{
			if (M == L) continue; ++i;
			const FVector Back = -L->GetActorForwardVector(), Side = L->GetActorRightVector();
			Give(M, EDukeOrder::Move, L->GetActorLocation() + Back * (220.f * i) + Side * ((i % 2) ? 140.f : -140.f));
		}
		return;
	}
	// Hold / Roadblock: occupation duties. The officer inspects the posts; troopers stand to attention as he passes.
	if (PatrolRoute.Num())
	{
		const FVector Goal = GetActorTransform().TransformPosition(PatrolRoute[PatrolIndex % PatrolRoute.Num()]);
		if (FVector::Dist2D(L->GetActorLocation(), Goal) < 120.f) { PatrolIndex = (PatrolIndex + 1) % PatrolRoute.Num(); L->PlayGesture(TEXT("command_point")); }
		Give(L, EDukeOrder::Move, Goal);
	}
	int32 Post = 0;
	for (ADukeTrooper* M : A)
	{
		if (M == L) continue;
		const bool bOfficerNear = L->Rank >= EDukeRank::Sergeant && FVector::Dist2D(M->GetActorLocation(), L->GetActorLocation()) < 350.f;
		switch (M->Duty)
		{
		case EDukeDuty::Logistics:
		{
			// haul crates between the depot and the drop-off, swapping every 14 s (offset per trooper)
			const int32 Leg = FMath::FloorToInt((T + M->GetUniqueID() % 7) / 14.f) % 2;
			Give(M, EDukeOrder::Duty, GetActorTransform().TransformPosition(Leg ? CrateDropoff : CratePickup), TEXT("carry_crate"));
			break;
		}
		case EDukeDuty::Radio:
			Give(M, EDukeOrder::Duty, L->GetActorLocation() + L->GetActorRightVector() * 180.f, TEXT("radio_call"), L); break;
		case EDukeDuty::Artillery:
			Give(M, EDukeOrder::Duty, GetActorTransform().TransformPosition(MortarPit), TEXT("attention")); break;   // stands by the mortar
		case EDukeDuty::Checkpoint:
			if (Checkpoint) { FVector At; AActor* Face = nullptr; const FName Step = Checkpoint->NextGateStep(M, At, Face); Give(M, EDukeOrder::Duty, At, Step, Face); break; }
			// fall through to sentry when there is no checkpoint
		default:
		{
			const float A0 = (Post++) * 2.f * PI / FMath::Max(1, A.Num() - 1);
			const FVector Spot = Base + FVector(FMath::Cos(A0), FMath::Sin(A0), 0.f) * 600.f;
			if (bOfficerNear) Give(M, EDukeOrder::Attention, M->GetActorLocation(), TEXT("attention"), L);
			else Give(M, EDukeOrder::Duty, Spot, TEXT("patrol_look"));
		}
		}
		if (bOfficerNear && M->Duty != EDukeDuty::Checkpoint && M->Duty != EDukeDuty::Logistics)
			Give(M, EDukeOrder::Attention, M->GetActorLocation(), TEXT("attention"), L);
	}
}

// Bounding overwatch: half the squad moves cover to cover toward the threat while the other half lays down covering fire.
void ADukeSquad::TickCombat(float Dt)
{
	const float T = Now();
	if (Threat.IsValid())
	{
		bool bSeen = false;
		for (ADukeTrooper* M : Alive()) if (M->CanFight() && HasLineOfSight(M->GetActorLocation() + FVector(0, 0, 70), Threat->GetActorLocation())) { bSeen = true; break; }
		if (bSeen) { ThreatLastSeen = Threat->GetActorLocation(); ThreatTime = T; }
	}
	if (T > NextBound) { BoundTeam ^= 1; NextBound = T + BoundSeconds; if (ADukeTrooper* L = Leader()) L->PlayGesture(TEXT("command_advance")); }
	int32 i = 0;
	for (ADukeTrooper* M : Alive())
	{
		if (!M->CanFight() || M->IsBusyRescuing()) continue;
		const int32 Team = (i++) % 2;
		FDukeOrderData O; O.Target = Threat; O.bAiming = true; O.Location = M->GetActorLocation();
		const float Dist = FVector::Dist2D(M->GetActorLocation(), ThreatLastSeen);
		if (M->Duty == EDukeDuty::Artillery && Dist > 1500.f)
		{
			// fire mission: drop rounds on the threat's last known position
			O.Type = EDukeOrder::Duty; O.Clip = TEXT("mortar_load"); O.Location = GetActorTransform().TransformPosition(MortarPit);
			if (FVector::Dist2D(M->GetActorLocation(), O.Location) < 150.f && (GStrikes.Num() == 0 || GStrikes.Last().When < T))
				GStrikes.Add({ ThreatLastSeen + FVector(FMath::FRandRange(-300.f, 300.f), FMath::FRandRange(-300.f, 300.f), 0.f), T + 3.f + 2.6f });
		}
		else if (M->Duty == EDukeDuty::Heavy || Team != BoundTeam || Dist < 700.f)
		{
			O.Type = EDukeOrder::Suppress;                     // covering fire
			FVector C; if (FindCover(M->GetActorLocation(), ThreatLastSeen, C) && FVector::Dist2D(C, M->GetActorLocation()) < 400.f) O.Location = C;
		}
		else
		{
			O.Type = EDukeOrder::Cover;                        // bound forward to the next cover
			const FVector Ahead = M->GetActorLocation() + (ThreatLastSeen - M->GetActorLocation()).GetSafeNormal2D() * 450.f;
			FVector C; O.Location = FindCover(Ahead, ThreatLastSeen, C) ? C : Ahead;
		}
		M->GiveOrder(O);
	}
}

// Wounded troopers are dragged to cover by the nearest healthy one (a medic if there is one close), while the rest keep firing.
void ADukeSquad::TickRescues()
{
	for (auto It = Rescues.CreateIterator(); It; ++It)
	{
		ADukeTrooper* W = It.Key().Get();
		if (!W || W->IsDead() || !W->IsWounded()) { It.RemoveCurrent(); continue; }
		ADukeTrooper* R = It.Value().Get();
		if (!R || R->IsDead() || !R->CanFight())
		{
			R = nullptr; float Best = 1e9f;
			for (ADukeTrooper* M : Alive())
			{
				if (M == W || !M->CanFight() || M->IsBusyRescuing() || M->Rank == EDukeRank::Officer) continue;
				float D = FVector::Dist2D(M->GetActorLocation(), W->GetActorLocation());
				if (M->Duty == EDukeDuty::Medic) D *= 0.5f;     // medics go first
				if (D < Best && D < 3000.f) { Best = D; R = M; }
			}
			It.Value() = R;
		}
		// where to: cover from the threat near the wounded man, else back toward the squad's rear
		FVector Safe = GetActorLocation();
		if (Threat.IsValid())
		{
			FVector C;
			if (FindCover(W->GetActorLocation(), ThreatLastSeen, C)) Safe = C;
			else Safe = W->GetActorLocation() - (ThreatLastSeen - W->GetActorLocation()).GetSafeNormal2D() * 600.f;
		}
		FDukeOrderData Crawl; Crawl.Type = EDukeOrder::Move; Crawl.Location = Safe; W->GiveOrder(Crawl);   // crawls toward it meanwhile
		if (R) { FDukeOrderData O; O.Type = EDukeOrder::Rescue; O.Target = W; O.Location = Safe; R->GiveOrder(O); }
	}
}

// Room clearing: stack on the door, the leader signals, the first pair breaches and clears, the rest follow.
void ADukeSquad::TickClearBuilding()
{
	if (!Doors.IsValidIndex(DoorIndex) || !Doors[DoorIndex]) { Mode = EDukeSquadMode::Hold; return; }
	const float T = Now() - ModeSince;
	AActor* D = Doors[DoorIndex];
	const FVector In = D->GetActorForwardVector(), Side = D->GetActorRightVector();
	int32 i = 0;
	ADukeTrooper* L = Leader();
	for (ADukeTrooper* M : Alive())
	{
		if (!M->CanFight()) continue;
		FDukeOrderData O; O.Target = D; O.bAiming = true;
		if (T < 4.f) { O.Type = EDukeOrder::Stack; O.Clip = TEXT("stack_up"); O.Location = D->GetActorLocation() - In * 80.f + Side * 90.f - In * (75.f * i); }
		else if (T < 4.5f) { if (M == L) M->PlayGesture(TEXT("command_advance")); O.Type = EDukeOrder::Stack; O.Clip = TEXT("stack_up"); O.Location = M->GetActorLocation(); }
		else
		{
			const float Go = 4.5f + 0.6f * i;    // one by one through the door, each takes a corner
			O.Type = T < Go ? EDukeOrder::Stack : EDukeOrder::Breach; O.Clip = TEXT("stack_up");
			O.Location = T < Go ? M->GetActorLocation() : D->GetActorLocation() + In * 300.f + Side * ((i % 2) ? 220.f : -220.f) + In * (60.f * (i / 2));
		}
		M->GiveOrder(O); ++i;
	}
	if (T > 4.5f + 0.6f * i + 3.f) { ++DoorIndex; ModeSince = Now(); }
}
